import React, { useMemo, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { tours } from '../data/mockData';
import SafeIcon from '../common/SafeIcon';
import { getStorageKey, readLocalEvents } from '../utils/localEvents';
import { seedTourDemoEvidence } from '../utils/demoEvidence';

function fallbackCopyText(text) {
  const textarea = document.createElement('textarea');
  textarea.value = text;
  textarea.setAttribute('readonly', '');
  textarea.style.position = 'fixed';
  textarea.style.left = '-9999px';
  document.body.appendChild(textarea);
  textarea.select();

  try {
    return document.execCommand('copy');
  } finally {
    textarea.remove();
  }
}

export default function Evidence() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [copyStatus, setCopyStatus] = useState('');
  const [refreshKey, setRefreshKey] = useState(0);
  const tour = tours.find(item => item.id === id) || tours[0];

  const evidence = useMemo(() => {
    const visitedStops = JSON.parse(localStorage.getItem(getStorageKey('progress', tour.id)) || '[]');
    const activatedOffers = JSON.parse(localStorage.getItem(getStorageKey('offers', tour.id)) || '[]');
    const savedStops = JSON.parse(localStorage.getItem(getStorageKey('saved-stops', tour.id)) || '[]');
    const fieldNote = localStorage.getItem(getStorageKey('field-note', tour.id)) || '';
    const offlinePackRaw = localStorage.getItem(`tour-engine:offline-pack:${tour.id}`);
    let offlinePack = null;
    if (offlinePackRaw) {
      try {
        offlinePack = JSON.parse(offlinePackRaw);
      } catch {
        offlinePack = { savedAt: 'saved', stops: [] };
      }
    }
    const loyaltyStamps = JSON.parse(localStorage.getItem(getStorageKey('loyalty', tour.id)) || '{}');
    const currentStopIndex = Number(localStorage.getItem(getStorageKey('current-stop-index', tour.id)) || 0);
    const currentStop = tour.stops?.[currentStopIndex] || null;
    const events = readLocalEvents().filter(event => event.payload?.tourId === tour.id);

    return {
      tourId: tour.id,
      tourTitle: tour.title,
      currentStopIndex,
      currentStopPosition: currentStop ? currentStopIndex + 1 : null,
      currentStopId: currentStop?.id || null,
      currentStopTitle: currentStop?.title || null,
      currentSourceStopNumber: currentStop?.number || null,
      visitedStops,
      activatedOffers,
      savedStops,
      fieldNote,
      offlinePack,
      loyaltyStamps,
      events
    };
  }, [tour.id, tour.title, tour.stops, refreshKey]);

  const completedStops = evidence.visitedStops.length;
  const activatedOfferCount = evidence.activatedOffers.length;
  const savedStopCount = evidence.savedStops.length;
  const fieldSignalCounts = evidence.events
    .filter(event => event.type === 'field_signal')
    .reduce((counts, event) => ({ ...counts, [event.payload?.signal || 'unknown']: (counts[event.payload?.signal || 'unknown'] || 0) + 1 }), {});
  const loyaltyStampCount = Object.values(evidence.loyaltyStamps).reduce((sum, count) => sum + Number(count || 0), 0);

  const getEvidenceJson = () => JSON.stringify({ exportedAt: new Date().toISOString(), ...evidence }, null, 2);

  const copyEvidence = async () => {
    const evidenceJson = getEvidenceJson();
    try {
      if (navigator.clipboard?.writeText) {
        await Promise.race([
          navigator.clipboard.writeText(evidenceJson),
          new Promise((_, reject) => window.setTimeout(() => reject(new Error('Clipboard timed out')), 1000))
        ]);
        setCopyStatus('Copied');
      } else {
        setCopyStatus(fallbackCopyText(evidenceJson) ? 'Copied' : 'Copy unavailable');
      }
    } catch {
      setCopyStatus(fallbackCopyText(evidenceJson) ? 'Copied' : 'Copy unavailable');
    }
    window.setTimeout(() => setCopyStatus(''), 2200);
  };

  const downloadEvidence = () => {
    const blob = new Blob([getEvidenceJson()], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `tour-engine-${tour.id}-field-evidence.json`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
  };

  const seedDemoEvidence = () => {
    seedTourDemoEvidence(tour);
    setRefreshKey(key => key + 1);
  };

  return (
    <div className="min-h-screen bg-[#FDFBF7] pb-8">
      <div className="sticky top-0 z-10 bg-white/90 px-5 py-4 shadow-sm backdrop-blur">
        <div className="flex items-center justify-between gap-3">
          <button onClick={() => navigate(`/player/${tour.id}`)} className="rounded-full bg-slate-100 p-2 text-slate-700">
            <SafeIcon name="ArrowLeft" className="h-5 w-5" />
          </button>
          <div className="text-center">
            <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Demo evidence</p>
            <h1 className="text-lg font-black text-slate-900">Local activity trail</h1>
          </div>
          <div className="relative flex items-center gap-2">
            <button onClick={downloadEvidence} aria-label="Download evidence JSON" className="rounded-full bg-blue-50 p-2 text-blue-700">
              <SafeIcon name="Download" className="h-5 w-5" />
            </button>
            <button onClick={copyEvidence} aria-label="Copy evidence JSON" className="rounded-full bg-emerald-50 p-2 text-emerald-700">
              <SafeIcon name="Copy" className="h-5 w-5" />
            </button>
            {copyStatus && (
              <span className="absolute right-0 top-10 whitespace-nowrap rounded-full bg-slate-900 px-2 py-1 text-[10px] font-bold text-white shadow">
                {copyStatus}
              </span>
            )}
          </div>
        </div>
      </div>

      <main className="px-5 pt-5">
        <section className="rounded-3xl bg-slate-900 p-5 text-white shadow-xl">
          <p className="text-[10px] font-bold uppercase tracking-widest text-orange-200">{tour.packId}</p>
          <h2 className="mt-2 text-2xl font-black leading-tight">{tour.title}</h2>
          <p className="mt-3 text-sm leading-relaxed text-slate-300">
            Browser-local proof that a tour can produce progress, offer, loyalty, and intent events before backend wiring exists.
          </p>
        </section>

        <section className="mt-4 rounded-3xl border border-orange-100 bg-orange-50 p-4 shadow-sm">
          <div className="flex items-center justify-between gap-3">
            <div>
              <p className="text-[10px] font-bold uppercase tracking-widest text-orange-700">Synthetic walkthrough</p>
              <p className="mt-1 text-xs leading-relaxed text-orange-950/80">Seed local-only demo progress, offer, loyalty, field note, offline pack, and event data for a reviewer-ready evidence page.</p>
            </div>
            <button onClick={seedDemoEvidence} className="rounded-full bg-orange-700 px-3 py-2 text-[10px] font-bold uppercase text-white shadow-sm">
              Seed demo
            </button>
          </div>
        </section>

        <section className="mt-4 grid grid-cols-2 gap-3">
          <div className="rounded-2xl border border-slate-100 bg-white p-4 shadow-sm">
            <p className="text-2xl font-black text-slate-900">{completedStops}</p>
            <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Visited</p>
          </div>
          <div className="rounded-2xl border border-slate-100 bg-white p-4 shadow-sm">
            <p className="text-2xl font-black text-slate-900">{savedStopCount}</p>
            <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Saved</p>
          </div>
          <div className="rounded-2xl border border-slate-100 bg-white p-4 shadow-sm">
            <p className="text-2xl font-black text-slate-900">{activatedOfferCount}</p>
            <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Offers</p>
          </div>
          <div className="rounded-2xl border border-slate-100 bg-white p-4 shadow-sm">
            <p className="text-2xl font-black text-slate-900">{loyaltyStampCount}</p>
            <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Stamps</p>
          </div>
        </section>

        <section className="mt-5 rounded-3xl border border-emerald-100 bg-emerald-50 p-5 shadow-sm">
          <div className="flex items-start justify-between gap-3">
            <div>
              <p className="text-[10px] font-bold uppercase tracking-widest text-emerald-700">Offline readiness</p>
              <h3 className="text-base font-black text-slate-900">{evidence.offlinePack ? 'Compact pack saved' : 'Compact pack not saved'}</h3>
              <p className="mt-2 text-xs leading-relaxed text-emerald-900/80">
                {evidence.offlinePack
                  ? `${evidence.offlinePack.stops?.length || 0} stops saved on this device for field testing.`
                  : 'Use Save Offline on the tour detail page before walking if you want this device to retain the compact route manifest.'}
              </p>
            </div>
            <span className="rounded-full bg-white px-2 py-1 text-[10px] font-bold uppercase text-emerald-700">
              {evidence.offlinePack ? 'saved' : 'missing'}
            </span>
          </div>
        </section>

        <section className="mt-5 rounded-3xl border border-blue-100 bg-blue-50 p-5 shadow-sm">
          <div className="mb-3 flex items-center justify-between gap-3">
            <div>
              <p className="text-[10px] font-bold uppercase tracking-widest text-blue-700">Field test summary</p>
              <h3 className="text-base font-black text-slate-900">What the walk captured</h3>
            </div>
            <span className="rounded-full bg-white px-2 py-1 text-[10px] font-bold uppercase text-blue-700">local</span>
          </div>
          <div className="mb-4 grid grid-cols-3 gap-2">
            {['useful', 'spammy', 'confusing'].map(signal => (
              <div key={signal} className="rounded-2xl bg-white p-3 text-center">
                <p className="text-xl font-black text-slate-900">{fieldSignalCounts[signal] || 0}</p>
                <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">{signal}</p>
              </div>
            ))}
          </div>
          <div className="rounded-2xl bg-white p-4">
            <p className="mb-2 text-[10px] font-bold uppercase tracking-widest text-slate-400">Freeform field note</p>
            <p className="whitespace-pre-wrap text-sm leading-relaxed text-slate-700">{evidence.fieldNote || 'No field note saved yet.'}</p>
          </div>
        </section>

        <section className="mt-5 rounded-3xl border border-slate-100 bg-white p-5 shadow-sm">
          <div className="mb-4 flex items-center justify-between gap-3">
            <div>
              <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Event stream</p>
              <h3 className="text-base font-black text-slate-900">Latest local events</h3>
            </div>
            <span className="rounded-full bg-slate-100 px-2 py-1 text-[10px] font-bold uppercase text-slate-500">local only</span>
          </div>

          {evidence.events.length === 0 ? (
            <div className="rounded-2xl bg-slate-50 p-4 text-sm text-slate-500">
              No local events yet. Activate an offer, add a demo loyalty stamp, or mark a stop visited in the player.
            </div>
          ) : (
            <div className="space-y-3">
              {evidence.events.map(event => (
                <div key={event.id} className="rounded-2xl bg-slate-50 p-3">
                  <div className="flex items-center justify-between gap-3">
                    <p className="text-sm font-bold capitalize text-slate-900">{event.type.replaceAll('_', ' ')}</p>
                    <p className="text-[10px] text-slate-400">{new Date(event.createdAt).toLocaleString()}</p>
                  </div>
                  <pre className="mt-2 overflow-x-auto rounded-xl bg-white p-2 text-[10px] leading-relaxed text-slate-500">{JSON.stringify(event.payload, null, 2)}</pre>
                </div>
              ))}
            </div>
          )}
        </section>
      </main>
    </div>
  );
}
